/bin/zsh -c "docker exec -i invoice-audit-contract-check psql -v ON_ERROR_STOP=1 -U postgres <<'SQL'
GRANT SELECT, UPDATE, DELETE ON accounts TO invoice_purge;
SET ROLE app;
SELECT purge_demo_account('demo');
RESET ROLE;
DO "'$$
BEGIN
  IF EXISTS (SELECT 1 FROM accounts WHERE id = '"'demo') OR EXISTS (SELECT 1 FROM orders WHERE account_id = 'demo') OR EXISTS (SELECT 1 FROM invoice_audit WHERE order_id = 'od') THEN
    RAISE EXCEPTION 'demo purge left rows behind';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM accounts WHERE id = 'real') OR NOT EXISTS (SELECT 1 FROM invoice_audit WHERE order_id = 'or') THEN
    RAISE EXCEPTION 'demo purge removed real account data';
  END IF;
END
"'$$;
